#!/usr/bin/env python3
"""reanchor2.py FROMREV [--apply] [--files f1,f2] : re-anchor citations of Specification chapters in test files,
mapping line numbers from FROMREV's version of each chapter to the working tree's by unchanged lines.
Default files: every .fss/.fsi/.test under ProjectFortress/{tests,compiler_tests,library_tests}."""
import re, os, sys, subprocess, difflib
ROOT='/home/user/fortress'
FROM=sys.argv[1]; apply='--apply' in sys.argv
files=None
for a in sys.argv:
    if a.startswith('--files='): files=a[8:].split(',')
CHAPS={'basic/overloading.tex','advanced/overloading.tex','basic/inference.tex','basic/conversions-coercions.tex',
       'basic/trait-parameters.tex','basic/types-vals-vars.tex','basic/functions.tex','basic/components/source-code.tex',
       'appendices/changes.tex','appendices/future.tex','appendices/overloading-function.tex'}
SHORT={'inference.tex':'basic/inference.tex','conversions-coercions.tex':'basic/conversions-coercions.tex',
       'trait-parameters.tex':'basic/trait-parameters.tex','types-vals-vars.tex':'basic/types-vals-vars.tex',
       'overloading.tex':'basic/overloading.tex','functions.tex':'basic/functions.tex','source-code.tex':'basic/components/source-code.tex',
       'changes.tex':'appendices/changes.tex','future.tex':'appendices/future.tex','overloading-function.tex':'appendices/overloading-function.tex'}
maps={}
def build(c):
    if c in maps: return maps[c]
    old=subprocess.run(['git','-C',ROOT,'show',f'{FROM}:Specification/{c}'],capture_output=True,text=True).stdout.split('\n')
    new=open(f'{ROOT}/Specification/{c}',encoding='utf-8').read().split('\n')
    sm=difflib.SequenceMatcher(None,old,new,autojunk=False); m={}; blocks=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=='equal':
            for k in range(i2-i1): m[i1+k+1]=j1+k+1
        else:
            for k in range(i1,i2): m[k+1]=None
            blocks.append((tag,i1+1,i2,j1+1,j2))
    maps[c]=(m,blocks); return maps[c]
def match(cur):
    for c in CHAPS:
        if cur==c or cur.endswith('/'+c): return c
    base=cur.split('/')[-1]
    if '/' not in cur and base in SHORT: return SHORT[base]
    return None
def mapline(c,n,end):
    m,blocks=build(c); v=m.get(n)
    if v is not None: return v,('moved' if v!=n else 'same')
    for tag,i1,i2,j1,j2 in blocks:
        if tag!='insert' and i1<=n<=i2: return (j2 if end else j1),'replaced'
    return n,'unmapped'
tok=re.compile(r'([A-Za-z0-9_./-]+\.tex)(:\d+(?:-\d+)?)?|(?<![A-Za-z0-9_.])(:\d+(?:-\d+)?)')
if files is None:
    files=[]
    for d in ['tests','compiler_tests','library_tests']:
        for dp,dn,fn in os.walk(os.path.join(ROOT,'ProjectFortress',d)):
            files+= [os.path.relpath(os.path.join(dp,f),ROOT) for f in sorted(fn) if f.endswith(('.fss','.fsi','.test'))]
for rel in files:
    p=os.path.join(ROOT,rel); lines=open(p,encoding='utf-8').read().split('\n'); dirty=False
    for i,line in enumerate(lines):
        cur=None; out=[]
        for mt in tok.finditer(line):
            if mt.group(1):
                cur=mt.group(1); c=match(cur); rng=mt.group(2); pos=mt.start(2) if rng else None
            else:
                c=match(cur) if cur else None; rng=mt.group(3); pos=mt.start(3)
            if not (c and rng): continue
            a,_,b=rng[1:].partition('-'); a=int(a); b=int(b) if b else None
            na,ka=mapline(c,a,False)
            nb,kb=(mapline(c,b,True) if b is not None else (None,'same'))
            new=':'+str(na)+(('-'+str(nb)) if nb is not None else '')
            if new!=rng or 'replaced' in (ka,kb) or 'unmapped' in (ka,kb):
                print(f'{rel}:{i+1}\t{c}{rng} -> {new}\t{ka},{kb}')
                if new!=rng: out.append((pos,pos+len(rng),new))
        if out:
            for s,e,new in sorted(out,reverse=True): line=line[:s]+new+line[e:]
            lines[i]=line; dirty=True
    if dirty and apply: open(p,'w',encoding='utf-8').write('\n'.join(lines))
